                  onClick={() => setQuizDifficulty(d)}
                  className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${
                    quizDifficulty === d ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-400'
                  }`}
                >
