              ))}
            </div>

            {loadingError && (
              <div className="p-4 bg-red-50 text-red-600 rounded-2xl text-[11px] font-bold border border-red-100 animate-fade-in flex flex-col gap-1">
                 <span>⚠️ Generation Failed</span>
