            {user.name || 'Student Enrollment'}
          </p>
        </div>
        <div className="bg-amber-50 px-4 py-2 rounded-2xl border border-amber-100 flex items-center gap-2">
          <span className="text-amber-500 font-bold">★</span>
          <span className="font-black text-slate-800">{totalPoints.toLocaleString()}</span>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto no-scrollbar bg-slate-50/30">
        {currentScreen === AppScreen.ENTRY && (
          <div className="p-8 animate-fade-in space-y-6 pb-24">
            <div className="text-center space-y-1">
              <h2 className="text-3xl font-black text-slate-900 tracking-tighter italic">Enroll to Excel</h2>
              <p className="text-slate-400 text-sm font-medium">Please provide your school details below.</p>
            </div>

            <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div className="col-span-2 space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Full Name</label>
                  <input type="text" value={user.name} onChange={e => setUser({...user, name: e.target.value})} className="input-field w-full px-5 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="e.g. Juan Luna" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Your School</label>
                  <input type="text" value={user.school} onChange={e => setUser({...user, school: e.target.value})} className="input-field w-full px-5 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="e.g. Quezon Science" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Section</label>
                  <input type="text" value={user.section} onChange={e => setUser({...user, section: e.target.value})} className="input-field w-full px-5 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="e.g. Diamond-A" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Grade Level</label>
                  <input type="text" value={user.gradeLevel} onChange={e => setUser({...user, gradeLevel: e.target.value})} className="input-field w-full px-5 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="Grade 12" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Subject</label>
                  <input type="text" value={user.subject} onChange={e => setUser({...user, subject: e.target.value})} className="input-field w-full px-5 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="Chemistry" />
                </div>
              </div>

              <div className="space-y-1 relative">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Specific Topic</label>
                <div className="relative">
                  <input type="text" value={user.topic} onChange={e => setUser({...user, topic: e.target.value})} className="input-field w-full pl-5 pr-12 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="e.g. Organic Bonds" />
                  <button onClick={startListening} className={`absolute right-1.5 top-1/2 -translate-y-1/2 w-9 h-9 rounded-xl flex items-center justify-center transition-all ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-white text-indigo-600 shadow-sm hover:shadow-md'}`}><MicIcon /></button>
                </div>
              </div>
            </div>

            <div className="flex bg-slate-200/50 p-1.5 rounded-2xl gap-1">
              {Object.values(Difficulty).map(d => (
                <button key={d} onClick={() => setDifficulty(d)} className={`flex-1 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${difficulty === d ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400'}`}>{d}</button>
              ))}
            </div>

            {error && (
              <div className="p-4 bg-red-50 text-red-600 rounded-2xl text-[11px] font-bold border border-red-100 animate-fade-in space-y-2">
                 <p className="uppercase tracking-widest flex items-center gap-2">⚠️ Configuration Error</p>
                 <p className="opacity-80 font-medium leading-relaxed">
                   {error.includes("API_KEY") 
                    ? "The API key is missing. Please ensure you have added a variable named 'API_KEY' in your Netlify/Vercel Environment Settings." 
                    : error}
                 </p>
              </div>
            )}

            <Button onClick={startQuiz} className="rounded-[2rem] h-16 text-lg font-black tracking-widest uppercase shadow-xl shadow-indigo-100">Proceed to Exam</Button>
          </div>
        )}

        {currentScreen === AppScreen.LOADING && (
          <div className="flex flex-col items-center justify-center h-full space-y-6 animate-fade-in">
             <div className="w-16 h-16 border-[6px] border-indigo-50 border-t-indigo-600 rounded-full animate-spin"></div>
             <div className="text-center">
               <h3 className="text-2xl font-black text-slate-900">Validating Enrollment</h3>
               <p className="text-[10px] text-slate-400 font-black uppercase tracking-widest mt-1">Generating high-quality exam content...</p>
             </div>
          </div>
        )}

        {currentScreen === AppScreen.QUIZ && activeQuiz && (
          <div className="p-8 h-full flex flex-col animate-fade-in">
             <div className="flex justify-between items-end mb-8">
                <div>
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Mastery Track</p>
                   <p className="text-4xl font-black">{currentIndex + 1}<span className="text-slate-200 text-xl">/{activeQuiz.questions.length}</span></p>
                </div>
                <div className="px-3 py-1 bg-indigo-50 rounded-full text-[10px] font-black text-indigo-600 uppercase border border-indigo-100">{activeQuiz.difficulty}</div>
             </div>

             <div className="flex-1 space-y-6 overflow-y-auto no-scrollbar pb-10">
                <div className="bg-white p-8 rounded-[2.5rem] shadow-xl shadow-indigo-50/50 border border-indigo-50">
                  <h2 className="text-xl font-bold text-slate-800 leading-snug">{activeQuiz.questions[currentIndex].text}</h2>
                </div>

                <div className="grid gap-3">
                  {activeQuiz.questions[currentIndex].options.map((opt, i) => {
                    let style = "bg-white border-slate-100 text-slate-600 hover:border-indigo-300";
                    if (feedback) {
                      if (i === activeQuiz.questions[currentIndex].correctIndex) style = "bg-emerald-50 border-emerald-500 text-emerald-700 shadow-emerald-50";
                      else if (i === feedback.selected && !feedback.isCorrect) style = "bg-red-50 border-red-500 text-red-700";
                      else style = "opacity-40 bg-slate-50 border-transparent grayscale scale-95";
                    }
                    return (
                      <button key={i} disabled={!!feedback} onClick={() => handleAnswer(i)} className={`w-full p-5 text-left rounded-2xl border-2 transition-all font-bold flex items-center gap-4 ${style}`}>
                        <span className={`w-8 h-8 rounded-xl flex items-center justify-center text-xs font-black ${feedback && i === activeQuiz.questions[currentIndex].correctIndex ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400'}`}>{String.fromCharCode(65 + i)}</span>
                        {opt}
                      </button>
                    );
                  })}
                </div>

                {feedback && (
                  <div className="animate-fade-in space-y-4 pt-4">
                    <div className={`p-6 rounded-[2rem] border-2 shadow-xl ${feedback.isCorrect ? 'bg-emerald-50 border-emerald-100' : 'bg-indigo-50 border-indigo-100'}`}>
                      <div className="flex justify-between items-center mb-3">
                        <p className={`text-[10px] font-black uppercase tracking-widest ${feedback.isCorrect ? 'text-emerald-600' : 'text-indigo-600'}`}>Learning Insight</p>
                        <button onClick={() => speak(activeQuiz.questions[currentIndex].explanation)} className="text-indigo-600 p-2 hover:bg-indigo-100 rounded-full transition-colors"><SpeakerIcon /></button>
                      </div>
                      <p className="text-sm font-bold text-slate-800 italic leading-relaxed">{activeQuiz.questions[currentIndex].explanation}</p>
                    </div>
                    {!feedback.isCorrect && <Button onClick={nextQuestion} className="rounded-2xl py-5 shadow-indigo-100 shadow-xl">Understood, Continue</Button>}
                  </div>
                )}
             </div>
          </div>
        )}

        {currentScreen === AppScreen.RESULTS && activeQuiz && (
          <div className="p-8 pb-32 animate-fade-in space-y-8">
