                   <div className="flex-1">
                      <p className="text-[9px] font-black text-slate-400 uppercase mb-1">Accuracy</p>
                      <p className="text-2xl font-black text-slate-800">{activeQuiz.score}/{activeQuiz.totalQuestions}</p>
                   </div>
