        </div>
        <div className="bg-amber-50 px-4 py-2 rounded-2xl border border-amber-100 flex items-center gap-2">
          <span className="text-amber-500 font-bold">★</span>
          <span className="font-black text-slate-800">{totalPoints.toLocaleString()}</span>
        </div>
      </header>

      <main className="flex-1 overflow-y-auto no-scrollbar bg-slate-50/30">
        {currentScreen === AppScreen.ENTRY && (
          <div className="p-8 animate-fade-in space-y-6 pb-24">
            <div className="text-center space-y-1">
              <h2 className="text-3xl font-black text-slate-900 tracking-tighter italic">Enroll to Excel</h2>
              <p className="text-slate-400 text-sm font-medium">Please provide your school details below.</p>
            </div>

            <div className="bg-white p-6 rounded-[2.5rem] shadow-sm border border-slate-100 space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div className="col-span-2 space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Full Name</label>
                  <input type="text" value={user.name} onChange={e => setUser({...user, name: e.target.value})} className="input-field w-full px-5 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="e.g. Juan Luna" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Your School</label>
                  <input type="text" value={user.school} onChange={e => setUser({...user, school: e.target.value})} className="input-field w-full px-5 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="e.g. Quezon Science" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest pl-2">Section</label>
                  <input type="text" value={user.section} onChange={e => setUser({...user, section: e.target.value})} className="input-field w-full px-5 py-3.5 rounded-2xl bg-slate-50 border-none font-bold text-slate-800" placeholder="e.g. Diamond-A" />
                </div>
