              ))}
            </div>

            {error && (
              <div className="p-4 bg-red-50 text-red-600 rounded-2xl text-[11px] font-bold border border-red-100 animate-fade-in space-y-2">
                 <p className="uppercase tracking-widest flex items-center gap-2">⚠️ Error</p>
                 <p className="opacity-80 font-medium leading-relaxed">
