import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Difficulty, QuizQuestion, UserProfile, ExamMode, QuestionType } from '../types';

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY missing");
  return new GoogleGenAI({ apiKey });
};

const fetchWithRetry = async <T>(fn: () => Promise<T>, retries: number = 2, delay: number = 1000): Promise<T> => {
  try {
    return await fn();
  } catch (error: any) {
    if (retries > 0 && (error.message?.includes('503') || error.message?.includes('429'))) {
      await new Promise(res => setTimeout(res, delay));
      return fetchWithRetry(fn, retries - 1, delay * 1.5);
    }
    throw error;
  }
};

export const generateQuizQuestions = async (
  profile: UserProfile,
  difficulty: Difficulty,
  count: number = 10
): Promise<QuizQuestion[]> => {
  return fetchWithRetry(async () => {
    const ai = getAI();

    const prompt = `Act as a Board Examiner for ${profile.board}. 
    Generate a 10-question Mock Exam batch for Grade ${profile.gradeLevel}, Subject: ${profile.subject}, Topic: ${profile.topic}.

    Mode: ${profile.examMode}. 
    Difficulty: ${difficulty}.

    Pattern Requirements:
    1. Include at least 2 "Case-Based Study" questions (Scenario + Question).
    2. Include at least 1 "Assertion-Reasoning" question.
    ${profile.examMode === ExamMode.FULL_PATTERN ? '3. Include 3 Theory/Descriptive questions with Model Answers and Marking Schemes.' : '3. Strictly Multiple Choice for all questions.'}

    Ensure questions are based on the latest 2024-25 sample papers.
    For Case Studies, provide the scenario in "caseText".
    For Theory, provide the question in "text" and detailed answer in "modelAnswer".

    Output JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: `You are a high-stakes Board Exam mock test generator. Focus on curriculum accuracy, marking schemes, and standard board question phrasing.`,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.INTEGER },
              type: { type: Type.STRING, enum: Object.values(QuestionType) },
              text: { type: Type.STRING },
              caseText: { type: Type.STRING },
              options: { type: Type.ARRAY, items: { type: Type.STRING } },
              correctIndex: { type: Type.INTEGER },
              explanation: { type: Type.STRING },
              modelAnswer: { type: Type.STRING },
              markingScheme: { type: Type.ARRAY, items: { type: Type.STRING } }
            },
            required: ["id", "type", "text", "explanation"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response.");
    return JSON.parse(text);
  });
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Board Exam Tip: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
        },
      },
    });
    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) throw new Error("Audio failed");
    const binaryString = atob(base64Audio);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes.buffer;
  } catch (error) {
    throw error;
  }
};

export const playAudioBuffer = async (buffer: ArrayBuffer) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const dataInt16 = new Int16Array(buffer);
  const audioBuffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = audioBuffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(ctx.destination);
  source.start();
};

