import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Difficulty, QuizQuestion, UserProfile, ExamMode, QuestionType } from '../types';

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY missing");
  return new GoogleGenAI({ apiKey });
};

export const generateQuizQuestions = async (
  profile: UserProfile,
  difficulty: Difficulty
): Promise<QuizQuestion[]> => {
  const ai = getAI();

  const prompt = `Act as a Senior CBSE Board Examiner for Academic Year 2024-2025.
  Generate exactly 10 high-quality questions for Grade ${profile.gradeLevel}, Subject: ${profile.subject}, Topic: ${profile.topic}.

  Strictly follow the 2025 CBSE Sample Paper Pattern:
  1. 4 MCQs (including 1 Assertion-Reasoning question).
  2. 2 Case-Based Questions (A scenario/text in 'caseText' + a question).
  3. 4 Subjective/Theory questions (2 Short Answer, 2 Long Answer style).

  For Theory questions:
  - Provide a 'modelAnswer'.
  - Provide a 'markingScheme' (step-by-step mark distribution).

  Additional Requirements:
  - 'boardFavoriteReason': Briefly explain why this question/concept is frequent in the last 10 years of CBSE exams.
  - 'visualDescription': If the question would normally have a diagram, describe it clearly in text so the student can visualize it.
  - 'explanation': Focus on "Concept Clarification" - make them understand the core NCERT principle.

  Ensure the difficulty matches: ${difficulty}. Output strictly as a JSON array.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: prompt,
    config: {
      systemInstruction: `You are a CBSE Mock Exam Generator. Your questions must be 100% syllabus aligned and mimic the specific wording of official board papers. Focus on clarifying misconceptions for students.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.INTEGER },
            type: { type: Type.STRING, enum: Object.values(QuestionType) },
            section: { type: Type.STRING },
            text: { type: Type.STRING },
            caseText: { type: Type.STRING },
            visualDescription: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctIndex: { type: Type.INTEGER },
            explanation: { type: Type.STRING },
            modelAnswer: { type: Type.STRING },
            markingScheme: { type: Type.ARRAY, items: { type: Type.STRING } },
            boardFavoriteReason: { type: Type.STRING }
          },
          required: ["id", "type", "text", "explanation"]
        }
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("AI failed to generate content.");
  return JSON.parse(text);
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Attention Scholar: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
    },
  });
  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio generation failed");
  const binaryString = atob(base64Audio);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes.buffer;
};

export const playAudioBuffer = async (buffer: ArrayBuffer) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const dataInt16 = new Int16Array(buffer);
  const audioBuffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = audioBuffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(ctx.destination);
  source.start();
};

