  const ai = getAI();

  const prompt = `Act as a Senior CBSE Board Examiner (2025). 
  Generate 10 high-yield questions for Grade ${profile.gradeLevel}, Subject: ${profile.subject}, Topic: ${profile.topic}.

  Pattern (Strictly 2025 Sample Paper):
  1. 4 MCQs (including 1 Assertion-Reasoning).
  2. 2 Case-Based Study questions (Provide scenario in 'caseText').
  3. 4 Subjective Theory questions (VSA/SA/LA mix).

  Requirements:
  - 'boardFavoriteReason': Why this concept is high-frequency in the last 10 years.
  - 'visualDescription': A detailed prompt for an image generator to create a diagram or graph for this question.
  - 'markingScheme': Point-by-point mark breakdown.
  - For MCQs/Assertion-Reason/Case-Study (if MCQ): Must have exactly 4 'options' and a 'correctIndex'.
  - For Subjective: Must have 'modelAnswer'.

  Output only valid JSON array.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      systemInstruction: `You are a specialized CBSE Exam Simulator. You generate high-quality, syllabus-aligned mock tests instantly. Focus on accuracy and marking schemes. Ensure every question has enough data to be interactive.`,
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.INTEGER },
            type: { type: Type.STRING, enum: Object.values(QuestionType) },
            section: { type: Type.STRING },
            text: { type: Type.STRING },
            caseText: { type: Type.STRING },
            visualDescription: { type: Type.STRING },
            options: { type: Type.ARRAY, items: { type: Type.STRING } },
            correctIndex: { type: Type.INTEGER },
            explanation: { type: Type.STRING },
            modelAnswer: { type: Type.STRING },
            markingScheme: { type: Type.ARRAY, items: { type: Type.STRING } },
            boardFavoriteReason: { type: Type.STRING }
          },
          required: ["id", "type", "text", "explanation"]
        }
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("AI failed to generate content.");
  return JSON.parse(text);
};

export const generateQuestionImage = async (description: string): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `Generate a clear, educational CBSE board exam diagram or illustration for: ${description}. White background, professional textbook style.` }]
      },
      config: {
        imageConfig: { aspectRatio: "16:9" }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    throw new Error("No image data found");
  } catch (err) {
    console.error("Image gen failed:", err);
    return "";
  }
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Board Alert: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
    },
  });
  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio generation failed");
  const binaryString = atob(base64Audio);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes.buffer;
};

export const playAudioBuffer = async (buffer: ArrayBuffer) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const dataInt16 = new Int16Array(buffer);
  const audioBuffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = audioBuffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(ctx.destination);
  source.start();
};

