import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Difficulty, QuizQuestion, UserProfile, BoardSection, QuestionType } from '../types';

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY missing");
  return new GoogleGenAI({ apiKey });
};

const QUESTION_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      type: { type: Type.STRING, enum: Object.values(QuestionType) },
      section: { type: Type.STRING },
      text: { type: Type.STRING },
      caseText: { type: Type.STRING },
      visualDescription: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctIndex: { type: Type.INTEGER },
      explanation: { type: Type.STRING },
      modelAnswer: { type: Type.STRING },
      markingScheme: { type: Type.ARRAY, items: { type: Type.STRING } },
      boardFavoriteReason: { type: Type.STRING }
    },
    required: ["id", "type", "text", "explanation"]
  }
};

export const generateQuizQuestions = async (
  profile: UserProfile,
  difficulty: Difficulty
): Promise<QuizQuestion[]> => {
  const ai = getAI();
  const topicContext = profile.isFullSyllabus ? "the Entire Syllabus" : `the Chapter: ${profile.topic}`;

  // To prevent timeouts and "AI Failed" errors on large requests, 
  // we optimize the count based on section.
  let count = 6; // default smaller batch for reliability
  let patternInfo = "";

  if (profile.selectedSection === BoardSection.FULL_MOCK) {
    count = 10;
    patternInfo = "Mix of Section A (MCQs), C (Short Answer), and E (Case Study).";
  } else if (profile.selectedSection === BoardSection.SECTION_A) {
    count = 10;
    patternInfo = "Strictly MCQs and 1 Assertion-Reasoning question.";
  } else {
    count = 5; // Subjective sections generate fewer but higher quality questions per batch
    patternInfo = `Strictly ${profile.selectedSection} style questions.`;
  }

  const prompt = `Act as a Senior CBSE Board Examiner (2025). 
  Generate ${count} high-yield questions for Grade ${profile.gradeLevel}, Subject: ${profile.subject}, covering ${topicContext}.

  Section Requirement: ${patternInfo}
  Difficulty: ${difficulty}.

  Rules:
  - 'boardFavoriteReason': Why this concept is high-frequency (last 10 years).
  - 'visualDescription': Detailed description for an image generator.
  - 'markingScheme': Required for non-MCQs.
  - MCQs: Must have exactly 4 options and correctIndex.

  Output only valid JSON array.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: `You are a specialized CBSE Exam Simulator. Generate accurate, syllabus-aligned mock tests. Use professional academic language.`,
        responseMimeType: "application/json",
        responseSchema: QUESTION_SCHEMA
      }
    });

    const text = response.text;
    if (!text) throw new Error("Empty response from AI");
    return JSON.parse(text);
  } catch (err) {
    console.error("Gemini Error:", err);
    throw err;
  }
};

export const generateQuestionImage = async (description: string): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `Generate a textbook-style educational diagram/illustration for CBSE Board Exam: ${description}. Clear lines, professional, white background.` }]
      },
      config: {
        imageConfig: { aspectRatio: "16:9" }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return "";
  } catch (err) {
    return "";
  }
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Exam Note: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
    },
  });
  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio generation failed");
  const binaryString = atob(base64Audio);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes.buffer;
};

export const playAudioBuffer = async (buffer: ArrayBuffer) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const dataInt16 = new Int16Array(buffer);
  const audioBuffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = audioBuffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(ctx.destination);
  source.start();
};

