  );
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Difficulty, QuizQuestion, UserProfile, BoardSection, QuestionType } from '../types';

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY missing");
  return new GoogleGenAI({ apiKey });
};

const QUESTION_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      type: { type: Type.STRING, enum: Object.values(QuestionType) },
      section: { type: Type.STRING },
      text: { type: Type.STRING },
      caseText: { type: Type.STRING },
      visualDescription: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctIndex: { type: Type.INTEGER },
      explanation: { type: Type.STRING },
      modelAnswer: { type: Type.STRING },
      markingScheme: { type: Type.ARRAY, items: { type: Type.STRING } },
      boardFavoriteReason: { type: Type.STRING }
    },
    required: ["id", "type", "text", "explanation"]
  }
};

/**
 * Utility to clean AI response text and ensure it's valid JSON
 */
const cleanJsonResponse = (text: string): string => {
  let cleaned = text.trim();
  // Remove markdown code blocks if present
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?/, '').replace(/```$/, '').trim();
  }
  return cleaned;
};

export const generateQuizQuestions = async (
  profile: UserProfile,
  difficulty: Difficulty
): Promise<QuizQuestion[]> => {
  const ai = getAI();
  const topicContext = profile.isFullSyllabus ? "the Entire Syllabus" : `the Chapter: ${profile.topic}`;

  let count = 6;
  let patternInfo = "";

  if (profile.selectedSection === BoardSection.FULL_MOCK) {
    count = 8; // Reduced slightly for better structural stability and speed
    patternInfo = "A balanced mix: 3 MCQs, 2 Case Studies, 3 Subjective questions.";
  } else if (profile.selectedSection === BoardSection.SECTION_A) {
    count = 10;
    patternInfo = "All 10 must be MCQs or Assertion-Reasoning.";
  } else {
    count = 5;
    patternInfo = `Strictly ${profile.selectedSection} style questions.`;
  }

  const prompt = `Act as a Senior CBSE Board Examiner (2025). 
  Generate ${count} high-yield questions for Grade ${profile.gradeLevel}, Subject: ${profile.subject}, covering ${topicContext}.

  Section Requirement: ${patternInfo}
  Difficulty: ${difficulty}.

  CONSTRAINTS:
  1. CONCISE TEXT: Keep 'explanation' and 'caseText' under 200 characters each.
  2. MARKING SCHEME: Max 3 points per question.
  3. BOARD FAVORITE: 1 short sentence only.
  4. NO TRUNCATION: Ensure the JSON array is fully closed.

  Output ONLY a raw JSON array.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: `You are a CBSE Exam Bot. You must generate valid JSON. Be brief and professional. Do not hallucinate massive blocks of text.`,
        responseMimeType: "application/json",
        responseSchema: QUESTION_SCHEMA,
        maxOutputTokens: 8192, // Increased to prevent truncation
        temperature: 0.7
      }
    });

    const rawText = response.text;
    if (!rawText) throw new Error("Empty response from AI");

    const cleanedText = cleanJsonResponse(rawText);
    return JSON.parse(cleanedText);
  } catch (err: any) {
    console.error("Gemini Error:", err);
    // If it's a parsing error, provide a cleaner message
    if (err instanceof SyntaxError) {
      throw new Error("AI returned malformed data. This usually happens when the topic is too complex. Try a specific Section instead.");
    }
    throw err;
  }
};

export const generateQuestionImage = async (description: string): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `CBSE Exam Diagram: ${description}. Clear, educational, white background.` }]
      },
      config: {
        imageConfig: { aspectRatio: "16:9" }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return "";
  } catch (err) {
    return "";
  }
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Exam Note: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
    },
  });
  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio generation failed");
  const binaryString = atob(base64Audio);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes.buffer;
};

export const playAudioBuffer = async (buffer: ArrayBuffer) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const dataInt16 = new Int16Array(buffer);
  const audioBuffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = audioBuffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(ctx.destination);
  source.start();
};

