import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Difficulty, QuizQuestion, UserProfile, BoardSection, QuestionType } from '../types';

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY missing");
  return new GoogleGenAI({ apiKey });
};

const QUESTION_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      type: { type: Type.STRING, enum: Object.values(QuestionType) },
      section: { type: Type.STRING },
      text: { type: Type.STRING },
      caseText: { type: Type.STRING },
      visualDescription: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctIndex: { type: Type.INTEGER },
      explanation: { type: Type.STRING },
      modelAnswer: { type: Type.STRING },
      markingScheme: { type: Type.ARRAY, items: { type: Type.STRING } },
      boardFavoriteReason: { type: Type.STRING }
    },
    required: ["id", "type", "text", "explanation"]
  }
};

/**
 * Attempts to repair common AI JSON truncation errors
 */
const repairJson = (text: string): string => {
  let cleaned = text.trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?/, '').replace(/```$/, '').trim();
  }

  // If JSON is cut off (unterminated), try to close the array/object
  // This is a basic safety net for the "Unterminated string" error
  let openBrackets = (cleaned.match(/\{/g) || []).length;
  let closedBrackets = (cleaned.match(/\}/g) || []).length;
  let openArrays = (cleaned.match(/\[/g) || []).length;
  let closedArrays = (cleaned.match(/\]/g) || []).length;

  while (openBrackets > closedBrackets) {
    cleaned += '}';
    closedBrackets++;
  }
  while (openArrays > closedArrays) {
    cleaned += ']';
    closedArrays++;
  }

  return cleaned;
};

export const generateQuizQuestions = async (
  profile: UserProfile,
  difficulty: Difficulty
): Promise<QuizQuestion[]> => {
  const ai = getAI();
  const topicContext = profile.isFullSyllabus ? "the Entire Syllabus" : `the Chapter: ${profile.topic}`;

  let count = 5;
  let patternInfo = "";

  if (profile.selectedSection === BoardSection.FULL_MOCK) {
    count = 7; // Reduced for reliability - covers A, B, C, D, E once.
    patternInfo = "Mix: 2 MCQs, 1 VSA, 1 SA, 1 LA, 1 Case Study, 1 Assertion-Reason.";
  } else if (profile.selectedSection === BoardSection.SECTION_A) {
    count = 10;
    patternInfo = "Strictly 10 MCQs/Assertion-Reason.";
  } else {
    count = 5;
    patternInfo = `Strictly ${profile.selectedSection} style.`;
  }

  const prompt = `Act as Senior Board Examiner for Grade ${profile.gradeLevel} ${profile.subject}.
  School: ${profile.school}, Section: ${profile.section}.
  Generate ${count} high-yield questions for ${topicContext}.

  Section: ${patternInfo}
  Difficulty: ${difficulty}.

  STRICT CONSTRAINTS (To avoid JSON errors):
  1. ALL string values MUST be under 120 characters. 
  2. 'explanation' must be a single short sentence.
  3. 'markingScheme' list max 2 points.
  4. 'caseText' must be very short.
  5. DO NOT provide lengthy model answers.

  Output only raw JSON array matching schema.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: `You are a CBSE Board Exam Generator. Output VALID, MINIFIED, and CONCISE JSON. Never exceed string limits.`,
        responseMimeType: "application/json",
        responseSchema: QUESTION_SCHEMA,
        maxOutputTokens: 2500,
        temperature: 0.1 // Lower temperature for more consistent JSON
      }
    });

    const rawText = response.text;
    if (!rawText) throw new Error("AI returned nothing.");

    const repairedText = repairJson(rawText);
    return JSON.parse(repairedText);
  } catch (err: any) {
    console.error("Gemini Failure:", err);
    if (err instanceof SyntaxError) {
      throw new Error("The board paper was too complex to generate in one go. Please try 'Section A' or 'Section E' specifically.");
    }
    throw err;
  }
};

export const generateQuestionImage = async (description: string): Promise<string> => {
  const ai = getAI();
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [{ text: `Small educational diagram: ${description}. Clear, simple, white background.` }]
      },
      config: {
        imageConfig: { aspectRatio: "16:9" }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }
    return "";
  } catch (err) {
    return "";
  }
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
    contents: [{ parts: [{ text: `Note: ${text}` }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
      },
    },
  });
  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Audio generation failed");
  const binaryString = atob(base64Audio);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes.buffer;
};

export const playAudioBuffer = async (buffer: ArrayBuffer) => {
  const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
  const dataInt16 = new Int16Array(buffer);
  const audioBuffer = ctx.createBuffer(1, dataInt16.length, 24000);
  const channelData = audioBuffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
  const source = ctx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(ctx.destination);
  source.start();
};

