      let msgIdx = 0;
      const interval = setInterval(() => {
        setLoadingMessage(messages[msgIdx % messages.length]);
        setLoadingStep(s => Math.min(s + 20, 100));
        msgIdx++;
      }, 1500);
      return () => clearInterval(interval);
    }
  }, [currentScreen]);

