import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Difficulty, QuizQuestion, UserProfile, BoardSection, QuestionType, ExamMode } from '../types';

const getAI = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY missing");
  return new GoogleGenAI({ apiKey });
};

const QUESTION_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      id: { type: Type.INTEGER },
      type: { type: Type.STRING, enum: Object.values(QuestionType) },
      section: { type: Type.STRING },
      text: { type: Type.STRING },
      caseText: { type: Type.STRING },
      options: { type: Type.ARRAY, items: { type: Type.STRING } },
      correctIndex: { type: Type.INTEGER },
      explanation: { type: Type.STRING },
      modelAnswer: { type: Type.STRING },
      markingScheme: { type: Type.ARRAY, items: { type: Type.STRING } },
      boardFavoriteReason: { type: Type.STRING }
    },
    required: ["id", "type", "text", "explanation"]
  }
};

const repairJson = (text: string): string => {
  let cleaned = text.trim();
  if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```(?:json)?/, '').replace(/```$/, '').trim();
  }
  let isInsideString = false;
  for (let i = 0; i < cleaned.length; i++) {
    if (cleaned[i] === '"' && (i === 0 || cleaned[i - 1] !== '\\')) isInsideString = !isInsideString;
  }
  if (isInsideString) cleaned += '"';
  const stack: string[] = [];
  for (let i = 0; i < cleaned.length; i++) {
    const char = cleaned[i];
    let insideStr = false;
    for(let j=0; j<=i; j++) { if (cleaned[j] === '"' && (j === 0 || cleaned[j - 1] !== '\\')) insideStr = !insideStr; }
    if (insideStr) continue;
    if (char === '{' || char === '[') stack.push(char);
    else if (char === '}' || char === ']') {
      const last = stack[stack.length - 1];
      if ((char === '}' && last === '{') || (char === ']' && last === '[')) stack.pop();
    }
  }
  while (stack.length > 0) {
    const last = stack.pop();
    if (last === '{') cleaned += '}';
    if (last === '[') cleaned += ']';
  }
  return cleaned;
};

export const generateQuizQuestions = async (profile: UserProfile): Promise<QuizQuestion[]> => {
  const ai = getAI();
  const topicContext = profile.isFullSyllabus ? "the Entire Syllabus" : `the Chapter: ${profile.topic}`;

  let count = profile.examMode === ExamMode.MCQ_ONLY ? 5 : 7;
  let patternGoal = profile.examMode === ExamMode.MCQ_ONLY 
    ? "Generate exactly 5 high-quality MCQs to test subject knowledge." 
    : "Generate a mixed mock paper (MCQs, Short Answer, Long Answer).";

  const prompt = `Act as a Master Educator for Grade ${profile.gradeLevel}.
  Student: ${profile.name} from ${profile.school} (Section ${profile.section}).
  Target: ${profile.subject}, ${topicContext}.
  Difficulty: ${profile.difficulty}.

  ${patternGoal}

  RULES:
  1. For MCQs, provide a 'proper explanation' that helps a student understand why the answer is correct if they chose wrong.
  2. Keep all text concise (max 150 chars per string).
  3. Ensure conceptual accuracy.

  Output only raw JSON array matching schema.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        systemInstruction: `You are a professional educational assessment generator. Output strictly valid JSON.`,
        responseMimeType: "application/json",
        responseSchema: QUESTION_SCHEMA,
        maxOutputTokens: 3000,
        temperature: 0.2
      }
    });

    return JSON.parse(repairJson(response.text || "[]"));
  } catch (err: any) {
    console.error("Gemini Error:", err);
    throw err;
  }
};

export const generateSpeech = async (text: string): Promise<ArrayBuffer> => {
  const ai = getAI();
  const response = await ai.models.generateContent({
    model: "gemini-2.5-flash-preview-tts",
