  const handleMCQ = (idx: number) => {
    if (feedback) return;
    const isCorrect = idx === activeQuiz?.questions[currentIndex].correctIndex;
    setFeedback({ selected: idx, isCorrect });
    if (activeQuiz) {
      if (isCorrect) activeQuiz.score++;
      activeQuiz.userAnswers[currentIndex] = idx;
