               <p className="text-indigo-100 text-[10px] opacity-80 uppercase tracking-widest font-bold">Personalized Board Simulator</p>
            </div>

            <div className="bg-white p-5 rounded-3xl border shadow-sm space-y-4">
               <div className="space-y-3 pb-3 border-b border-slate-50">
                  <div className="space-y-1">
