                    <button onClick={() => setUser({...user, examMode: ExamMode.CBSE_FULL_PATTERN})} className={`py-3 rounded-xl text-[10px] font-black uppercase border ${user.examMode === ExamMode.CBSE_FULL_PATTERN ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-slate-50 text-slate-400 border-slate-100'}`}>Full Mock</button>
                  </div>
               </div>
            </div>

            <Button onClick={startQuiz} className="h-14 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl shadow-indigo-100">Start Session</Button>
            {error && <p className="text-center text-red-500 text-[10px] font-black uppercase bg-red-50 p-3 rounded-xl border border-red-100">{error}</p>}
          </div>
